  let session:any=null,user:any=null,profile:any=null,isAdmin=false,groups:Group[]=[],posts:Post[]=[],comments:any[]=[],notifications:any[]=[],reports:any[]=[],feedbacks:any[]=[],people:any[]=[],friendships:any[]=[],notificationChannel:any=null;
