  const cats=['Todos','Software','Programación','Inteligencia artificial','Ciberseguridad','Gaming','Tecnología','Diseño','Educación','Ciencia','Emprendimiento','Comunidad general','Otros'];let groupRatings:any[]=[];let myGroupRatings=new Map<string,number>();const activeJoined=()=>groups.filter(g=>g.joined&&!g.rules?.includes('[readonly]'));
