const profileFieldValue=(key:string)=>{if(key==="nombre")return profile?.display_name||"";if(key==="bio")return profile?.bio||"";if(key==="habilidades")return (profile?.skills||[]).map((x:any)=>typeof x==="string"?x:x.name||x.label||"").join(", ");if(key==="herramientas")return (profile?.tools||[]).map((x:any)=>typeof x==="string"?x:x.name||x.label||"").join(", ");if(key==="proyectos")return (profile?.projects||[]).map((x:any)=>[x.name||"",x.url||"",x.description||""].join(" | ")).join("\n");if(key==="enlaces")return (profile?.links||[]).map((x:any)=>[x.label||"",x.url||""].join(" | ")).join("\n");return "";};
